      {
        "question": "7.7 Complaints 7.7.1 Process The laboratory shall have a process for handling complaints that shall include at least the following: a) a description of the process for receiving, substantiating and investigating the complaint, and deciding what actions shall be taken in response;"
      },
      {
        "question": "b) tracking and recording the complaint, including the actions undertaken to resolve it;"
      },
      {
        "question": "c) ensuring appropriate action is taken."
      },
      {
        "question": "A description of the process for handling complaints shall be publicly available."
      },
      {
        "question": "7.7.2 Receipt of complaint a) Upon receipt of a complaint, the laboratory shall confirm whether the complaint relates to laboratory activities that the laboratory is responsible for and, if so, shall resolve the complaint. (see 8.7.1)."
      },
      {
        "question": "b) The laboratory receiving the complaint shall be responsible for gathering all necessary information to determine whether the complaint is substantiated."
      },
      {
        "question": "c) Whenever possible the laboratory shall acknowledge receipt of the complaint, and provide the complainant with the outcome and, if applicable, progress reports."
      },
      {
        "question": "7.7.3 Resolution of complaint Investigation and resolution of complaints shall not result in any discriminatory actions. The resolution of complaints shall be made by, or reviewed and approved by, persons not involved in the subject of the complaint in question. Where resources do not permit this, any alternative approach shall not compromise impartiality."
      }
