        "question": "Laboratory management shall ensure that appropriate laboratory advice and interpretation are available and meet the needs of patients and users.\r\nThe laboratory shall establish arrangements for communicating with laboratory users on the following when applicable:\r\na) advising on choice and use of examinations, including required type of sample, clinical indications\r\nand limitations of examination methods, and the frequency of requesting the examination;\r\nb) providing professional judgments on the interpretation of the results of examinations;\r\nc) promoting the effective utilization of laboratory examinations;\r\nd) advising on scientific and logistical matters such as instances of failure of sample(s) to meet acceptability criteria."
