        "question": "The laboratory shall authorize personnel to perform specific laboratory activities, including but not limited to, the following:\r\na) selection, development, modification, validation and verification of methods;\r\nb) review, release, and reporting of results;\r\nc) use of laboratory information systems, in particular: accessing patient data and information, entering patient data and examination results, changing patient data or examination results."
