    "Documents and Records Management":  [
      {
        "question": "8.2 Management system documentation\r\n8.2.1 General\r\nLaboratory management shall establish, document, and maintain objectives and policies for the fulfilment of the purposes of this document and shall ensure that the objectives and policies are acknowledged and implemented at all levels of the laboratory organization.\r\nNOTE The management system documents can, but are not required to, be contained in a quality manual."
      },
      {
        "question": "8.2.2 Competence and quality\r\nThe objectives and policies shall address the competence, quality and consistent operation of the laboratory."
      },
      {
        "question": "8.2.3 Evidence of commitment\r\nLaboratory management shall provide evidence of commitment to the development and implementation of the management system and to continually improving its effectiveness."
      },
      {
        "question": "8.2.4 Documentation\r\nAll documentation, processes, systems, and records, related to the fulfilment of the requirements of this document shall be included in, referenced from, or linked to the management system."
      },
      {
        "question": "8.2.5 Personnel access\r\nAll personnel involved in laboratory activities shall have access to the parts of the management system documentation and related information that are applicable to their responsibilities."
      },
      {
        "question": "8.3 Control of management system documents\r\n8.3.1 General\r\nThe laboratory shall control the documents (internal and external) that relate to the fulfilment of this document.\r\nNOTE In this context, \"document\" can be policy statements, procedures and related job aids, flow charts, instructions for use, specifications, manufacturer's instructions, calibration tables, biological reference intervals and their origins, charts, posters, notices, memoranda, software documentation, drawings, plans, agreements, and documents of external origin such as laws, regulations, standards and textbooks from which examination methods are taken, documents describing personnel qualifications (such as job descriptions), etc. These can be in any form or type of medium, such as hard copy or digital."
      },
      {
        "question": "8.3.2 Control of documents\r\nThe laboratory shall ensure that:\r\na) documents are uniquely identified;\r\nb) documents are approved for adequacy before issue by authorized personnel who have the expertise and competence to determine adequacy;\r\nc) documents are periodically reviewed and updated as necessary;\r\nd) relevant versions of applicable documents are available at points of use and, where necessary, their distribution is controlled;\r\ne) changes and the current revision status of documents are identified;\r\nf) documents are protected from unauthorized changes and any deletion or removal;\r\ng) documents are protected from unauthorized access;\r\nh) the unintended use of obsolete documents is prevented, and suitable identification is applied to them if they are retained for any purpose;\r\ni) at least one paper or electronic copy of each obsolete controlled document is retained for a specified time period or in accordance with applicable specified requirements."
      },
      {
        "question": "8.4 Control of records\r\n8.4.1 Creation of records\r\nThe laboratory shall establish and retain legible records to demonstrate fulfilment of the requirements of this document.\r\nRecords shall be created at the time each activity that affects the quality of an examination is performed.\r\nNOTE Records can be in any form or type of medium."
      },
      {
        "question": "8.4.2 Amendment of records\r\nThe laboratory shall ensure that amendments to records can be traced to previous versions or to original observations. Both the original and amended data and files shall be kept, including the date and where relevant, the time, of alteration, an indication of the altered aspects and the personnel making the alterations."
      },
      {
        "question": "8.4.3 Retention of records\r\na) The laboratory shall implement the procedures needed for the identification, storage, protection from unauthorized access and changes, back-up, archive, retrieval, retention time, and disposal of its records.\r\nb) The retention times for records shall be specified.\r\nNOTE 1 In addition to requirements, retention times can be chosen based on identified risks.\r\nc) Reported examination results shall be retrievable for as long as necessary or as required.\r\nd) All records shall be accessible throughout the entire retention period, legible in whichever medium the laboratory keeps records, and available for laboratory management review (see 8.9).\r\nNOTE 2 Legal liability concerns regarding certain types of procedures (e.g. histology examinations, genetic examinations, pediatric examinations) can require the retention of certain records for much longer times than for other records."
      }
    ],
